using System.Diagnostics;
using System.Reflection;
using API.Interfaces;
using API.Interfaces.Steps;
using Xunit;

namespace redux_tests;
#pragma warning disable CS1591

// Every solver can be stopped by the compute time limit (#935). A typed solver (ISolver<T, TPartial>) is stopped by its
// recorder, so it must report steps while it searches; a legacy solver is stopped by the timerHasExpired flag, so it
// must check the flag in its main loops and then answer SolveRun.TimedOutAnswer (one timeout answer for every solver,
// never "{}" or "timeout", which look like answers).
//
// The check is behavioural: each solver runs on its problem's default instance with the limit already passed (the flag
// set, or a recorder whose deadline is now), and must stop instead of answering. A solver that never checks fails here.
// The real-clock tests below run the slow brute-force searches on instances they cannot finish and check they stop
// within a second of a short limit, which also catches a check that sits only outside the expensive loop.
public class SolverTimeLimit_Tests {
    // Solvers that cannot be stopped by a check of their own, with the reason. Keep this short.
    private static readonly Dictionary<string, string> Allowlist = new() {
        // A placeholder for DummyVisualization: it does no work and has no problem, so no default instance.
        ["DummySolver"] = "does no work (placeholder for DummyVisualization)",
        // The quantum solvers make one call to the quantum service and block on its reply, so there is no loop to
        // check (#523's open question). The call is bounded by the HttpClient's 30 s timeout and, past the limit, by the
        // endpoint backstop; stopping the wait itself needs the call to take a cancellation token (#936/#937).
        ["BernsteinVaziraniQuantumSolver"] = "one blocking call to the quantum service",
        ["DeutschQuantumSolver"] = "one blocking call to the quantum service",
        ["DeutschJozsaQuantumSolver"] = "one blocking call to the quantum service",
        ["ShorsQuantumSolver"] = "one blocking call to the quantum service",
        ["SATGroverSolver"] = "one blocking call to the quantum service",
        ["UnstructuredGroverSolver"] = "one blocking call to the quantum service",
    };

    public static TheoryData<string> AllSolvers {
        get {
            var data = new TheoryData<string>();
            foreach (var type in ProblemProvider.Solvers.Values.OrderBy(t => t.Name, StringComparer.Ordinal))
                data.Add(type.Name);
            return data;
        }
    }

