    public static TheoryData<string, string> HardInstances {
        get {
            var data = new TheoryData<string, string>();
            foreach (var (solver, instance) in Hard) data.Add(solver, instance);
            return data;
        }
    }

    private static Type SolverType(string name) => ProblemProvider.Solvers[name.ToLower()];

    private static Type? TypedInterface(Type solver) =>
        solver.GetInterfaces().FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(ISolver<,>));

    internal static string DefaultInstance(Type solver) {
        Type problem = ProblemProvider.ProblemTypeOf(solver, typeof(ISolver<>))
            ?? throw new InvalidOperationException($"{solver.Name} declares no ISolver<T>, so it has no default instance.");
        return ((IProblem)Activator.CreateInstance(problem)!).defaultInstance;
    }

    [Theory]
    [MemberData(nameof(AllSolvers))]
    public void EverySolver_StopsWhenTheTimeLimitHasPassed(string name) {
        if (Allowlist.ContainsKey(name)) return;
        Type type = SolverType(name);
        string instance = DefaultInstance(type);
        var solver = (ISolver)Activator.CreateInstance(type)!;

        if (TypedInterface(type) is { } typed) {
            // Call Solve with a recorder whose deadline is now: the solver's first reported step must stop it.
            Type problemType = typed.GetGenericArguments()[0];
            Type partial = typed.GetGenericArguments()[1];
            object problem = ParseGuard.CreateProblem(problemType, instance);
            object rec = typeof(StepRecorder<>).MakeGenericType(partial)
                .GetMethod(nameof(StepRecorder<object>.DeadlineOnly))!.Invoke(null, new object[] { TimeSpan.Zero })!;
            var ex = Assert.Throws<TargetInvocationException>(() => typed.GetMethod("Solve")!.Invoke(solver, new[] { problem, rec }));
            Assert.IsType<StepBudgetExceededException>(ex.InnerException);
        } else {
            solver.timerHasExpired = true;
            string answer = solver.solve(instance);
            Assert.Equal(SolveRun.TimedOutAnswer, answer);
        }
    }

    [Fact]
    public void Allowlist_NamesOnlyRealSolvers() {
        foreach (var name in Allowlist.Keys)
            Assert.True(ProblemProvider.Solvers.ContainsKey(name.ToLower()), $"{name} is allowlisted but is not a solver");
    }
}

// The real-clock half of SolverTimeLimit_Tests: on an instance it cannot finish, each slow solver stops within a
// second of a 200 ms limit, through ISolver.Run as the endpoints call it.
[Collection(TimingCollection.Name)]
public class SolverTimeLimit_RealClock_Tests {
    [Theory]
    [MemberData(nameof(SolverTimeLimit_Tests.HardInstances), MemberType = typeof(SolverTimeLimit_Tests))]
    public void SlowSolve_StopsSoonAfterTheLimit(string name, string instance) {
        var solver = (ISolver)Activator.CreateInstance(ProblemProvider.Solvers[name.ToLower()])!;
        var sw = Stopwatch.StartNew();
        var run = solver.Run(instance, withSteps: false, TimeSpan.FromMilliseconds(200));
        sw.Stop();
        Assert.True(run.TimedOut, $"{name} finished in {sw.Elapsed} with {run.Answer}; the instance is not hard enough");
        Assert.Equal(SolveRun.TimedOutAnswer, run.Answer);
        Assert.True(sw.Elapsed < TimeSpan.FromMilliseconds(1200), $"{name} took {sw.Elapsed} to stop");
    }
}
